-- Unreviewed/new articles remain private to IT until a publisher selects otherwise.
alter table public.knowledge_articles add column audience text not null default 'it_only' check(audience in ('employees','it_only'));
grant insert(audience),update(audience) on public.knowledge_articles to authenticated;
create index knowledge_articles_audience_idx on public.knowledge_articles(organization_id,audience,status,updated_at desc,id);
drop policy knowledge_article_read on public.knowledge_articles;
create policy knowledge_article_read on public.knowledge_articles for select to authenticated using(
 (select private.is_active_organization_member(organization_id)) and
 ((select private.can_work_tickets(organization_id)) or (status='published' and audience='employees')));

-- Dependent attachments, Storage, related articles and invoker search inherit article RLS.
drop policy knowledge_feedback_read on public.knowledge_article_feedback;
create policy knowledge_feedback_read on public.knowledge_article_feedback for select to authenticated using(
 (select private.can_work_tickets(organization_id)) or
 (user_id=(select auth.uid()) and (select private.is_active_organization_member(organization_id)) and
 exists(select 1 from public.knowledge_articles a where a.id=article_id and a.organization_id=knowledge_article_feedback.organization_id)));

create or replace function private.record_audit_event()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  previous jsonb := case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
  current_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  org uuid; actor uuid := auth.uid(); actor_label text; target uuid; target_label text;
  fields text[]; key text; before_value jsonb; after_value jsonb; delta jsonb := '[]'::jsonb;
  ticket_number bigint;
begin
  org := case when tg_table_name='organizations' then (current_row->>'id')::uuid else (current_row->>'organization_id')::uuid end;
  target := coalesce(current_row->>'id',current_row->>'user_id')::uuid;
  -- Only the trusted service-role invitation RPC supplies an actor context.
  if actor is null and current_setting('role',true)='service_role' then
    actor := nullif(current_setting('app.audit_actor',true),'')::uuid;
  end if;
  select display_name into actor_label from public.profiles where organization_id=org and user_id=actor;
  actor_label := coalesce(actor_label,case when actor is null then 'System' else 'Member '||actor::text end);
  case tg_table_name
    when 'tickets' then fields:=array['title','description','status','priority','requester_id','assigned_technician_id','team_id','category_id','subcategory_id','location_id','due_at']; target_label:='Ticket #'||(current_row->>'ticket_number');
    when 'organization_memberships' then
      fields:=array['role','status'];
      select display_name into target_label from public.profiles where organization_id=org and user_id=target;
      if target_label is null and current_setting('role',true)='service_role' and current_row->>'user_id'=current_setting('app.audit_subject',true) then target_label:=nullif(current_setting('app.audit_subject_name',true),''); end if;
      target_label:=coalesce(target_label,'Member '||target::text);
    when 'organizations' then fields:=array['name','slug','logo_path']; target_label:=current_row->>'name';
    when 'profiles' then fields:=array['display_name','department_id','location_id']; target_label:=current_row->>'display_name';
    when 'departments' then fields:=array['name','description','is_active']; target_label:=current_row->>'name';
    when 'locations' then fields:=array['name','timezone','is_active']; target_label:=current_row->>'name';
    when 'teams' then fields:=array['name','is_active']; target_label:=current_row->>'name';
    when 'ticket_categories' then fields:=array['name','is_active','default_team_id']; target_label:=current_row->>'name';
    when 'ticket_subcategories' then fields:=array['name','category_id','is_active']; target_label:=current_row->>'name';
    when 'knowledge_articles' then fields:=array['title','category','status','audience','content','related_article_ids']; target_label:=current_row->>'title';
    when 'chat_conversations' then fields:=array['status','assigned_technician_id','ticket_id']; target_label:='Chat '||left(target::text,8);
    when 'ticket_messages' then
      fields:=array['kind','body'];
      select t.ticket_number into ticket_number from public.tickets t where t.organization_id=org and t.id=(current_row->>'ticket_id')::uuid;
      target_label:=coalesce('Ticket #'||ticket_number,'Ticket')||case when current_row->>'kind'='internal_note' then ' · internal note' else ' · public reply' end;
    else raise exception 'Unsupported audit source';
  end case;
  foreach key in array fields loop
    before_value:=case when tg_op='INSERT' then 'null'::jsonb else previous->key end;
    after_value:=case when tg_op='DELETE' then 'null'::jsonb else current_row->key end;
    if before_value is distinct from after_value then
      -- Record that content changed, never duplicate bodies, notes, or storage paths.
      if key in ('description','body','content','logo_path','related_article_ids') then
        before_value:=case when before_value is null or before_value='null'::jsonb then 'null'::jsonb else '"Previous content"'::jsonb end;
        after_value:=case when after_value is null or after_value='null'::jsonb then 'null'::jsonb else '"Content updated"'::jsonb end;
      else
        before_value:=private.audit_display_value(org,key,before_value);
        after_value:=private.audit_display_value(org,key,after_value);
      end if;
      delta:=delta||jsonb_build_array(jsonb_build_object('field',key,'from',before_value,'to',after_value));
    end if;
  end loop;
  if tg_op='UPDATE' and jsonb_array_length(delta)=0 then return new; end if;
  insert into public.audit_events(organization_id,actor_id,actor_name,entity_type,entity_id,entity_label,action,changes)
  values(org,actor,actor_label,tg_table_name,target,coalesce(target_label,tg_table_name),case tg_op when 'INSERT' then 'created' when 'DELETE' then 'deleted' else 'updated' end,delta);
  return case when tg_op='DELETE' then old else new end;
end $$;

create or replace function private.record_product_view(event_name text,org uuid,target_id uuid,event_surface text,event_token uuid)
returns void language plpgsql security definer set search_path='' as $$
declare actor_role public.app_role; session_key text:=auth.jwt()->>'session_id'; dedup text;
begin
  if auth.uid() is null or session_key is null or not private.has_required_assurance() then return; end if;
  if org is null and event_name='login' then select organization_id into org from public.organization_memberships where user_id=auth.uid() and status='active' order by created_at limit 1; end if;
  select role into actor_role from public.organization_memberships where organization_id=org and user_id=auth.uid() and status='active';
  if actor_role is null then return; end if;
  case event_name
    when 'login' then
      if event_surface<>'workspace' then return; end if;
      dedup:='login:'||session_key;
    when 'ticket_viewed' then
      if event_surface<>'tickets' or not exists(select 1 from public.tickets where id=target_id and organization_id=org and (actor_role<>'end_user' or requester_id=auth.uid())) then return; end if;
      dedup:='ticket_viewed:'||session_key||':'||target_id::text||':'||(now() at time zone 'UTC')::date::text;
    when 'knowledge_article_viewed' then
      if event_surface<>'knowledge' or not exists(select 1 from public.knowledge_articles where id=target_id and organization_id=org and (actor_role<>'end_user' or (status='published' and audience='employees'))) then return; end if;
      dedup:='knowledge_article_viewed:'||session_key||':'||target_id::text||':'||(now() at time zone 'UTC')::date::text;
    when 'search_performed' then
      if event_surface not in ('tickets','knowledge') or event_token is null then return; end if;
      dedup:='search_performed:'||session_key||':'||event_token::text;
    else return; -- Mutation and not-yet-built asset events cannot be forged here.
  end case;
  perform private.increment_product_usage(org,event_name,event_surface,dedup,case when event_name='login' then interval '90 days' else interval '1 day' end);
exception when others then return;
end $$;

-- Only reviewed, unchanged employee guides without unreviewed attachments are exposed.
with reviewed as (select * from jsonb_to_recordset('[{"id":"9d8d0fdc-6b97-5f24-8c23-250b3488533d","hash":"cf083655494a9b9e39ae56b40d04ba49","title":"A printer is offline or your document will not print","summary":"Check the selected printer and your own print job without disrupting shared equipment."},{"id":"90d21f7d-e78a-51fb-bd77-949a79b4b325","hash":"c83d8d8be668158d2920e1129de418f7","title":"A website will not load or the browser stops responding","summary":"Narrow down a website problem while protecting unsaved work and account access."},{"id":"034e6914-6a64-5d6a-97d7-a61bb71f201c","hash":"4d2d22f1cfaeed1d656a70a2a50cd8bc","title":"A work service or VPN will not connect","summary":"Separate internet, remote-access, and account problems before contacting IT."},{"id":"32613b98-d99a-59b4-9449-d2f660b988f1","hash":"ee7469bb254ca5f15d9d3a3a66ad3fb2","title":"An external monitor is blank or shows no signal","summary":"Check power, input selection, and the connection to your computer or dock."},{"id":"9294ebdd-5378-57a8-9140-30a2fb38621b","hash":"59fa3892b2651d56b6446b509572d23e","title":"Check a Windows computer that is running slowly","summary":"Save work, check storage, and describe the slowdown before making major changes."},{"id":"a2c5efa6-cd40-5b83-a257-d50ac5f580c0","hash":"03eae11989b6b79760b98413df83dcfd","title":"Create and update an Outlook meeting invitation","summary":"Invite attendees, check the time zone, and send changes to participants."},{"id":"2aa89451-488d-56d3-b330-206e01b91017","hash":"c8b64934e60c6c8ba862372ddc5b759e","title":"Export a Word document to PDF","summary":"Keep the editable original and check the exported file before sharing."},{"id":"42e8c860-ee84-5d23-8dcb-e74ffbac7bd4","hash":"1eb0a9f35c45e255b5e8d416a2d16050","title":"Find a missing email or an expected reset message","summary":"Check the right mailbox and folders before asking for another copy."},{"id":"ddad230d-5013-5cc1-b5e3-8ea5fb5a9586","hash":"76eeb20fe2c5abc077299a266a092e16","title":"Find official help articles and service-status information","summary":"Start with trusted support libraries and use status pages as one troubleshooting clue."},{"id":"ba1e40a0-29a9-5cfd-8fd0-80fd2b2ee438","hash":"ac33e25abd5da7b9dccffed031029359","title":"Find or restore a deleted cloud file","summary":"Check the correct account, recycle bin, and file owner without deleting other copies."},{"id":"9f8b062f-8f1f-55e2-958d-78ce4237324f","hash":"ae80b0d1ffc69c8f6e2b92985d4549ef","title":"Fix a camera that will not work in Teams","summary":"Check the camera selection, privacy shutter, and allowed permissions."},{"id":"f790e6ac-7886-5c37-bfb2-5baf3a45a2c2","hash":"9ceb73fb250d9a473fb4eab5065e351e","title":"Fix microphone or speaker problems in Teams","summary":"Check mute controls and the selected audio devices before reconnecting."},{"id":"f389ee69-25e8-5475-a8d5-c0f3f74cab0a","hash":"54bd26956c669471959f558339ccb279","title":"FixxFlow: add ticket attachments and browse earlier history","summary":"For everyone. Share useful evidence and find older messages without losing a draft."},{"id":"02ed0a57-c2c7-52ad-9523-00f4497f5900","hash":"dae87807e7b563fe4e4f00bd6dec4f98","title":"FixxFlow: check notification email behavior and contact FixxFlow support","summary":"For everyone. Know where email replies go and what the support action actually does."},{"id":"adce07a0-32f6-562e-b455-b03fed2d362d","hash":"442057f005ae1d6aafaf1ed2174fd004","title":"FixxFlow: create a ticket for yourself or another requester","summary":"For everyone. Record an issue clearly and use staff assignment controls when available."},{"id":"bb57836b-2ff0-518c-96b1-3a76448db65d","hash":"233039ffc0ea6d03fa26ab347251de80","title":"FixxFlow: find help articles and give useful feedback","summary":"For everyone. Browse topics, search guides, and tell IT whether an answer helped."},{"id":"bafbc76c-ee93-5146-8b2b-f21d0349db75","hash":"ec6ffdba017464043c8dbeb4949293b7","title":"FixxFlow: get started and find the right feature","summary":"For everyone. Learn where to request help, manage work, and find feature instructions."},{"id":"98422bbe-7344-526e-b1b1-ae6a7b88dc1f","hash":"c6eeccfdaf71cb09e6f2160f33d0a9ee","title":"FixxFlow: read and manage ticket and chat notifications","summary":"For everyone. Find updates, open the relevant conversation, and mark notifications read."},{"id":"2ce04863-c96d-532a-8c7e-95f39cb6419f","hash":"966ba044ec69ea9d2ab97f5a311a163d","title":"FixxFlow: recover from failed saves and protect unfinished work","summary":"For everyone. Keep drafts while resolving errors, stale edits, and uncertain network responses."},{"id":"611e7b9c-ff8d-5261-a17f-d66c931007ca","hash":"6358a479d1be9b032a0952b72100e8cf","title":"FixxFlow: request department equipment or supplies","summary":"For authorized inventory requesters. Request an item for an approved department and track fulfillment in a ticket."},{"id":"523c733c-f017-55d8-aec7-6d35f938eb0e","hash":"2cb233df7c9131166532bc7c1eca4f54","title":"FixxFlow: search the workspace and navigate with the keyboard","summary":"For everyone. Find permitted tickets, articles, people, and navigation destinations."},{"id":"e98082df-ed82-518e-b3a1-f8a6255e4a22","hash":"cc7bf271f8eea80e5ff64c456cde8800","title":"FixxFlow: start a support chat and continue the conversation","summary":"For everyone. Ask IT a question, share evidence, and return to the same chat later."},{"id":"a1e97af3-3cdc-5235-8916-2ec8cab99fd1","hash":"8c4df7f72292a26883a220e35e062716","title":"FixxFlow: update your profile, timezone, and appearance","summary":"For everyone. Keep contact details current and choose how FixxFlow looks and displays time."},{"id":"38c3911c-b5e1-5262-90c3-eac260d45197","hash":"cf744e30c1de2cc850d71bb9fa7f358b","title":"FixxFlow: view your equipment and request help for a device","summary":"For employees. Find assigned equipment and create a request linked to the right asset."},{"id":"79f38af1-c562-5a81-965a-f612fb178663","hash":"78337fd9b99350e01da9c7904db45a15","title":"Follow a ticket, reply to IT, or reopen an issue","summary":"Find your request, understand its status, and keep the troubleshooting conversation in one place."},{"id":"4dbe634e-2677-5c9a-94e8-8e00bf0792cf","hash":"9572846650c1fce73b4ba540d1c4a6af","title":"Get help and submit a useful IT request","summary":"Choose chat or a ticket, describe the impact, and give IT the details needed to help."},{"id":"53058304-6539-53c4-a3af-f379010a2378","hash":"1466554027acdccff1b48c92f02f951a","title":"Install approved updates on a work computer","summary":"Plan for restarts and follow managed Windows or Mac update settings."},{"id":"635393dc-5f98-5e04-a987-013a29b4f5df","hash":"1856b4caa678a0a3a2963d4a2ca76a60","title":"Join a Teams meeting and use meeting chat","summary":"Find the right invitation, join with your work account, and understand meeting-chat access."},{"id":"3926f65c-15c6-5649-8538-9140d9f54827","hash":"dd34fd26ad1646a08e6e3de17370884f","title":"Report a lost or stolen work device","summary":"Give IT the information needed to assess account access and protect workplace information."},{"id":"d885467c-9dbc-5c83-acf8-8ea75b2b2de5","hash":"e1aa4408cdc2c6a84eac159fe9737e52","title":"Report a suspicious email, message, or sign-in request","summary":"Recognize suspicious requests and tell IT promptly, including if you already interacted."},{"id":"553901f4-a7e3-5823-9db9-5846554fd86f","hash":"5f3595e6fdc773078efe0f120ae12c07","title":"Request software or access to a work application","summary":"Give IT the business need and access details without sharing accounts or installing unapproved software."},{"id":"569b6b4f-a84c-5e28-b9c6-60b049ea1561","hash":"11663f2f5bf7cad5812c2a1922476bdb","title":"Reset your FixxFlow password","summary":"Recover access to FixxFlow and troubleshoot a missing or expired reset email."},{"id":"0d43fa3f-985a-56b4-a3ac-287621c61690","hash":"ecd622464f30816d20aa1bf0f33be422","title":"Respond to a fake technical-support warning","summary":"Recognize unsolicited repair demands and report any interaction promptly."},{"id":"ba1bddf7-3d0b-54e6-84e0-fb0b5b3bdd9d","hash":"c5f06c628c58a0d8f083df2326df9344","title":"Save and recover work in Word, Excel, and PowerPoint","summary":"Understand AutoSave, preserve copies, and check recovery after a crash."},{"id":"301e4aaa-f04e-5a9a-a9d6-fcf0b2063929","hash":"0a78fada43333e8cd147332a54105314","title":"Set up an authenticator for FixxFlow","summary":"Add a second sign-in check and prepare a backup before changing phones."},{"id":"a4b94660-5ecf-59a9-90cb-b0f840983aad","hash":"775cb207a10fedd37b4acb621baab479","title":"Share a screen or window in a Teams meeting","summary":"Present the intended content while keeping unrelated information out of view."},{"id":"89237b55-4c11-5c3d-bb4e-08c5c2d9d696","hash":"b09f6ab969a20756e3c9f698f4df21b8","title":"Share a work file with the right people","summary":"Use named recipients and the minimum access needed for approved cloud storage."},{"id":"2ab9e4a0-edd4-5fe8-95be-9aed747f124a","hash":"4e36aa2d5d3e45c78aeeb68c8198acb9","title":"Troubleshoot a file that will not sync with OneDrive","summary":"Check the account, sync status, and space before changing files."},{"id":"55caf5ae-7c5d-5a67-ad0d-6ab421d435ff","hash":"304c80a3d75c1f2491c2b4ae14b4575a","title":"Troubleshoot a mouse or keyboard that stops responding","summary":"Check power, cables, and the intended wireless connection."},{"id":"eefe9ecb-0357-56bc-ab5a-f8590045d5b6","hash":"920dc88e91a3924d3ea9a64d459e9489","title":"Troubleshoot email that will not send or receive","summary":"Identify whether the issue affects one message, your mail app, or the mailbox itself."},{"id":"43b42295-a91f-5d1e-9615-8fafb22518c2","hash":"71142ee42501d3deffd85fcaa6c87f84","title":"Troubleshoot Excel formulas and unexpected results","summary":"Distinguish displayed formulas, text cells, and calculation errors."},{"id":"a6b8265b-63d3-5280-9568-807c6eb804a7","hash":"f0897e9919e48352cef2611567fc5cab","title":"Troubleshoot Wi-Fi or an unavailable internet connection","summary":"Check whether a connection problem affects your device, one service, or other people."}]'::jsonb) as r(id uuid,hash text,title text,summary text))
update public.knowledge_articles a set audience='employees' from reviewed r
where a.id=r.id and md5(a.content::text)=r.hash and a.title=r.title and a.summary=r.summary and a.status='published'
 and not exists(select 1 from public.knowledge_attachments k where k.article_id=a.id);

-- Update only reviewed instructional text; concurrent customer edits are preserved.
update public.knowledge_articles set content='[{"text":"For technicians and administrators. Write a structured guide, preview it, and publish only when ready. Available controls depend on your workspace role and permissions.","type":"paragraph"},{"text":"1. Create the draft","type":"heading"},{"text":"Open Knowledge base and choose New article. Enter Title, Category, Summary, Publication status, and Audience. Start with Draft and IT only. Employee-facing articles become available to employees only when published; IT only articles remain private to technicians and administrators.","type":"paragraph"},{"text":"2. Build clear content blocks","type":"heading"},{"text":"Add headings, paragraphs, lists, quotes, code, links, or image blocks as needed. Use the visible Move up, Move down, and Remove buttons to arrange blocks. Bold and italic use the editor’s formatting controls or its supported markers. Use full HTTP(S) URLs for links.","type":"paragraph"},{"text":"3. Save before uploading files","type":"heading"},{"text":"Create the article first. In Images and attachments, add a JPG, PNG, WebP, PDF, text, Word, or Excel file up to 6 MB. Choose an uploaded image in an image block and write a meaningful image description. Files follow the article’s access.","type":"paragraph"},{"text":"4. Preview and publish","type":"heading"},{"text":"Review Content preview, choose up to eight Related articles, and save. When ready, set Publication status to Published and confirm the intended Audience and save again. An uploaded file alone does not save unsent edits to article text.","type":"paragraph"},{"text":"Check the result","type":"heading"},{"text":"The article renders with readable headings, correct links, and useful image descriptions. Staff can reopen the draft; employees see it only when it is published and Employee-facing.","type":"paragraph"},{"text":"When to contact IT","type":"heading"},{"text":"If saving conflicts with another edit, preserve your text and coordinate before reloading. If upload completion is uncertain, check the attachment list in another tab before retrying.","type":"paragraph"}]'::jsonb where id='43f5e4f5-8062-5bd8-9e82-b225c0fc0b28'::uuid and md5(content::text)='bb62ab53d3f03779c78eaa42eb8451cc';
update public.knowledge_articles set content='[{"text":"For technicians and administrators. Keep published guidance accurate without exposing unfinished revisions. Available controls depend on your workspace role and permissions.","type":"paragraph"},{"text":"1. Find the article","type":"heading"},{"text":"Open Knowledge base and use the staff view that includes drafts. Search the title and open the guide. Review Article insights for daily-reader views and current helpful/not-helpful votes.","type":"paragraph"},{"text":"2. Choose how to revise","type":"heading"},{"text":"Editing a Published article changes the live article when saved; there is no separate unpublished revision. If changes must remain private while being developed, set Publication status to Draft and save before editing further.","type":"paragraph"},{"text":"3. Review content and access","type":"heading"},{"text":"Check steps, screenshots, links, attachments, and Related articles against the current workflow. Check Audience before publishing. Keep technical procedures IT only and employee self-service guidance Employee-facing; never include passwords or tokens. Existing attachment links stop working for readers who lose article access.","type":"paragraph"},{"text":"4. Publish or archive deliberately","type":"heading"},{"text":"Save the updated article and review its rendered page. Set Publication status to Published when ready and confirm Audience, or Archived when it should no longer be current guidance. Draft and Archived articles remain staff-only; archiving does not delete history.","type":"paragraph"},{"text":"Check the result","type":"heading"},{"text":"The article has the intended visibility and corrected content. Current vote totals are feedback signals, not proof that every reader completed the task.","type":"paragraph"},{"text":"When to contact IT","type":"heading"},{"text":"Coordinate if another editor saved a newer revision. If article access or file visibility is wrong, ask an administrator to investigate before republishing.","type":"paragraph"}]'::jsonb where id='92fe9954-9810-5a6b-83c1-651650683bca'::uuid and md5(content::text)='72b6f22d90b6a1856e62841c75caf6a5';
update public.knowledge_articles set content='[{"text":"This guide covers the employee ticket view. Your organization’s IT team manages assignment and priority.","type":"paragraph"},{"text":"What to do","type":"heading"},{"text":"1. Open your request","type":"heading"},{"text":"Choose My tickets, then select the relevant subject. Search using words from the title or the ticket number. Check the latest reply before sending another message.","type":"paragraph"},{"text":"2. Understand the status","type":"heading"},{"text":"New means the request has been recorded. Open or In progress means it is being handled. Waiting on user means IT needs information from you. On hold means work is paused. Resolved means a solution has been recorded; Closed means the request has been closed.","type":"paragraph"},{"text":"3. Reply with the missing details","type":"heading"},{"text":"Use the reply field to answer IT’s questions. Describe what changed and whether the suggested fix helped. Add an attachment when it explains the problem, removing unrelated personal or customer information first.","type":"paragraph"},{"text":"4. Reopen the same problem","type":"heading"},{"text":"If a resolved or closed request still has the same issue, choose Reopen ticket near the top of the ticket. Explain what is still happening, then submit Reopen ticket. For a different problem, create a new request instead.","type":"paragraph"},{"text":"Check the result","type":"heading"},{"text":"Confirm your reply appears in the conversation or the reopened ticket shows its new status. Do not repeatedly resubmit while a request is sending.","type":"paragraph"},{"text":"When to contact IT","type":"heading"},{"text":"If the ticket will not load or a reply fails, keep the unsent text and retry. If work is blocked, use your established IT contact method and include the ticket number.","type":"paragraph"}]'::jsonb where id='79f38af1-c562-5a81-965a-f612fb178663'::uuid and md5(content::text)='78337fd9b99350e01da9c7904db45a15';
